/**
 * SEA-RAFT optical flow on the device (on-device test of the hybrid measurement: eyes = the app's tracker with the
 * mirror step, other tasks = SEA-RAFT; tools/blender/BENCH.md 'method comparison'). The model (Spring 'M', BSD-3,
 * exported by tools/bench/export_searaft.py) runs in onnxruntime-web: WebGPU when the browser has it, else WASM.
 *
 * Crops follow the bench exactly (tools/bench/ext_track.py): one square around the rest landmarks (box × 1.5) cut
 * from the rest image and from each expression image alike (no head alignment), resized to RAFT_SIZE; the rest
 * points are moved by the flow sampled at them.
 */
import { applySimilarity, fitSimilarity } from '../core/geometry';
import { ALIGNMENT_ANCHORS } from '../core/landmarks';
import type { FrameObservation } from '../core/types';
import { DETECTED_ONLY } from './track';

export const RAFT_SIZE = 512;
export const RAFT_MODEL = 'models/searaft_M_512.onnx';
/** onnxruntime-web runtime files, copied into public/ort by scripts/copy-wasm.mjs. */
const ORT_DIR = 'ort/';

/** Square crop around the rest face in source pixels. */
export interface RaftBox {
  x: number;
  y: number;
  s: number;
}

/** An image cut to the rest box: RGB bytes, planar (R plane, G plane, B plane), RAFT_SIZE². */
export type RaftCrop = Uint8Array;

export interface RaftEngine {
  backend: 'webgpu' | 'wasm';
  /** Flow from a to b: [dx plane, dy plane], RAFT_SIZE² each, in crop pixels. */
  flow(a: RaftCrop, b: RaftCrop): Promise<Float32Array>;
}

const N_FACE = 468;
const px = (o: FrameObservation, i: number) => ({ x: o.landmarks[3 * i]! * o.width, y: o.landmarks[3 * i + 1]! * o.height });

/** The bench's crop box: the rest landmarks' bounding square × 1.5. */
export function raftBox(rest: FrameObservation): RaftBox {
  let x0 = Infinity,
    y0 = Infinity,
    x1 = -Infinity,
    y1 = -Infinity;
  for (let i = 0; i < N_FACE; i++) {
    const p = px(rest, i);
    x0 = Math.min(x0, p.x);
    y0 = Math.min(y0, p.y);
    x1 = Math.max(x1, p.x);
    y1 = Math.max(y1, p.y);
  }
  const s = Math.max(x1 - x0, y1 - y0) * 1.5;
  return { x: (x0 + x1) / 2 - s / 2, y: (y0 + y1) / 2 - s / 2, s };
}

let canvas: HTMLCanvasElement | OffscreenCanvas | null = null;

/** `src` (in the observation's pixel frame) cut to `box` and resized to RAFT_SIZE; black outside the image. */
export function raftCrop(src: CanvasImageSource, box: RaftBox): RaftCrop | null {
  const S = RAFT_SIZE;
  const c = (canvas ??=
    typeof OffscreenCanvas !== 'undefined'
      ? new OffscreenCanvas(S, S)
      : Object.assign(document.createElement('canvas'), { width: S, height: S }));
  const ctx = c.getContext('2d', { willReadFrequently: true }) as CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D | null;
  if (!ctx) return null;
  const k = S / box.s;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, S, S);
  ctx.imageSmoothingEnabled = true;
  ctx.setTransform(k, 0, 0, k, -box.x * k, -box.y * k);
  ctx.drawImage(src, 0, 0);
  const d = ctx.getImageData(0, 0, S, S).data;
  const out = new Uint8Array(3 * S * S);
  for (let i = 0, n = S * S; i < n; i++) {
    out[i] = d[4 * i]!;
    out[n + i] = d[4 * i + 1]!;
    out[2 * n + i] = d[4 * i + 2]!;
  }
  return out;
}

/** Bilinear sample of one flow plane at continuous point (x, y), pixel centres at +0.5, edges clamped. */
function sample(plane: Float32Array, off: number, x: number, y: number): number {
  const S = RAFT_SIZE;
  const fx = Math.min(S - 1, Math.max(0, x - 0.5));
  const fy = Math.min(S - 1, Math.max(0, y - 0.5));
  const x0 = Math.floor(fx),
    y0 = Math.floor(fy);
  const x1 = Math.min(S - 1, x0 + 1),
    y1 = Math.min(S - 1, y0 + 1);
  const ax = fx - x0,
    ay = fy - y0;
  const v = (xx: number, yy: number) => plane[off + yy * S + xx]!;
  return (1 - ay) * ((1 - ax) * v(x0, y0) + ax * v(x1, y0)) + ay * ((1 - ax) * v(x0, y1) + ax * v(x1, y1));
}

/**
 * The expression frame's observation from the flow: points 0–467 = rest points moved by the flow, iris points =
 * the rest iris moved by the anchors' similarity (as the bench's external runs); the rest of `det` is kept, and so
 * are its chin points (track.ts DETECTED_ONLY).
 */
export function raftObservation(rest: FrameObservation, det: FrameObservation, box: RaftBox, flow: Float32Array): FrameObservation {
  const S = RAFT_SIZE;
  const k = S / box.s;
  const lm = Array.from(rest.landmarks);
  for (let i = 0; i < N_FACE; i++) {
    if (DETECTED_ONLY.has(i)) {
      for (let c = 0; c < 3; c++) lm[3 * i + c] = det.landmarks[3 * i + c]!;
      continue;
    }
    const p = px(rest, i);
    const qx = (p.x - box.x) * k,
      qy = (p.y - box.y) * k;
    const x = (qx + sample(flow, 0, qx, qy)) / k + box.x;
    const y = (qy + sample(flow, S * S, qx, qy)) / k + box.y;
    lm[3 * i] = x / det.width;
    lm[3 * i + 1] = y / det.height;
  }
  const T = fitSimilarity(
    ALIGNMENT_ANCHORS.map((i) => px(rest, i)),
    ALIGNMENT_ANCHORS.map((i) => ({ x: lm[3 * i]! * det.width, y: lm[3 * i + 1]! * det.height })),
  );
  for (let i = N_FACE; i < lm.length / 3; i++) {
    const q = applySimilarity(T, px(rest, i));
    lm[3 * i] = q.x / det.width;
    lm[3 * i + 1] = q.y / det.height;
  }
  return { ...det, landmarks: lm };
}

let engine: Promise<RaftEngine> | null = null;

/**
 * Loads the runtime and the model once (≈ 79 MB model + 28 MB runtime on first use; the service worker keeps them).
 * `onProgress(fraction)` follows the model download; `forceWasm` skips WebGPU (tests of the fallback).
 */
export function loadRaft(onProgress?: (f: number) => void, forceWasm = false): Promise<RaftEngine> {
  engine ??= (async () => {
    const base = new URL('./', document.baseURI).href;
    // Fetched here (the service worker caches it, and the download shows progress), run in the worker.
    const model = await fetchWithProgress(base + RAFT_MODEL, onProgress);
    const worker = new Worker(new URL('./raft.worker.ts', import.meta.url), { type: 'module' });
    const waiting = new Map<number, { ok: (f: Float32Array) => void; fail: (e: Error) => void }>();
    let ready: { ok: (b: RaftEngine['backend']) => void; fail: (e: Error) => void } | null = null;
    worker.onmessage = (e: MessageEvent) => {
      const m = e.data as
        | { type: 'ready'; backend: RaftEngine['backend'] }
        | { type: 'flow'; id: number; flow: Float32Array }
        | { type: 'error'; id?: number; message: string };
      if (m.type === 'ready') ready?.ok(m.backend);
      else if (m.type === 'flow') {
        waiting.get(m.id)?.ok(m.flow);
        waiting.delete(m.id);
      } else if (m.id !== undefined && waiting.has(m.id)) {
        waiting.get(m.id)!.fail(new Error(m.message));
        waiting.delete(m.id);
      } else ready?.fail(new Error(m.message));
    };
    worker.onerror = (e) => {
      const err = new Error(e.message || 'SEA-RAFT worker failed');
      ready?.fail(err);
      waiting.forEach((w) => w.fail(err));
      waiting.clear();
    };
    const backend = await new Promise<RaftEngine['backend']>((ok, fail) => {
      ready = { ok, fail };
      worker.postMessage({ type: 'load', base: base + ORT_DIR, model: model.buffer, forceWasm }, [model.buffer]);
    });
    ready = null;
    let next = 0;
    return {
      backend,
      flow: (a, b) =>
        new Promise<Float32Array>((ok, fail) => {
          const id = ++next;
          waiting.set(id, { ok, fail });
          worker.postMessage({ type: 'flow', id, a, b });
        }),
    };
  })();
  engine.catch(() => (engine = null));
  return engine;
}

async function fetchWithProgress(url: string, onProgress?: (f: number) => void): Promise<Uint8Array> {
  const res = await fetch(url);
  if (!res.ok || !res.body) throw new Error(`SEA-RAFT model: HTTP ${res.status}`);
  const total = Number(res.headers.get('content-length')) || 0;
  const reader = res.body.getReader();
  const parts: Uint8Array[] = [];
  let got = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    parts.push(value);
    got += value.length;
    if (total) onProgress?.(got / total);
  }
  const out = new Uint8Array(got);
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return out;
}
